    assertNonEmptyString(note_id, 'note_id');

    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`Unknown note_id: ${note_id}`);
    }
    return textContent(`Note ${note.id}\nTitle: ${note.title}\nBody: ${note.body}`);
  }

  throw new Error(`Unknown tool: ${name}`);
}"}

