        }
      },
      required: ['note_id'],
      additionalProperties: false
    }
  }
];

function textContent(text) {
  return { content: [{ type: 'text', text }] };
}

function assertNonEmptyString(value, fieldName) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error(`Invalid arguments: ${fieldName} must be a non-empty string`);
  }
}

export async function listTools() {
  return TOOL_DEFINITIONS.slice();
}

export async function callTool(name, args) {
  if (typeof name !== 'string' || name.length === 0) {
    throw new Error('Invalid tool name');
  }

  const safeArgs = args && typeof args === 'object' ? args : {};

  if (name === 'note_create') {
    const { title, body } = safeArgs;
    assertNonEmptyString(title, 'title');
    assertNonEmptyString(body, 'body');

    const id = `n${nextId++}`;
    notes.set(id, { id, title, body });
    return textContent(`Created note ${id} with title "${title}".`);
  }

  if (name === 'note_get') {
    const { note_id } = safeArgs;
    assertNonEmptyString(note_id, 'note_id');

    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`Unknown note_id: ${note_id}`);
    }
    return textContent(`Note ${note.id}\nTitle: ${note.title}\nBody: ${note.body}`);
  }

  throw new Error(`Unknown tool: ${name}`);
}

