import('./server.mjs').then(async ({listTools, callTool}) => {
  // Test listTools structure
  const tools = await listTools();
  console.log('Tool count:', tools.length);
  console.log('Tool names:', tools.map(t => t.name));
  console.log('Has additionalProperties:false on note_create:', tools[0].inputSchema.additionalProperties === false);
  console.log('Has additionalProperties:false on note_get:', tools[1].inputSchema.additionalProperties === false);
  console.log('Required fields on note_create:', tools[0].inputSchema.required);
  console.log('Required fields on note_get:', tools[1].inputSchema.required);

  // Test invalid input - empty title
  try {
    await callTool('note_create', {title: '', body: 'B'});
    console.log('FAIL: empty title accepted');
  } catch (e) { console.log('OK: empty title rejected ->', e.message); }

  // Test invalid input - missing body
  try {
    await callTool('note_create', {title: 'A'});
    console.log('FAIL: missing body accepted');
  } catch (e) { console.log('OK: missing body rejected ->', e.message); }

  // Test invalid input - wrong type
  try {
    await callTool('note_create', {title: 123, body: 'B'});
    console.log('FAIL: non-string title accepted');
  } catch (e) { console.log('OK: non-string title rejected ->', e.message); }

  // Test invalid note_get - missing id
  try {
    await callTool('note_get', {});
    console.log('FAIL: missing note_id accepted');
  } catch (e) { console.log('OK: missing note_id rejected ->', e.message); }

  // Test unknown note
  try {
    await callTool('note_get', {note_id: 'n999'});
    console.log('FAIL: unknown note accepted');
  } catch (e) { console.log('OK: unknown note rejected ->', e.message); }

  // Test unknown tool
  try {
    await callTool('note_other', {});
    console.log('FAIL: unknown tool accepted');
  } catch (e) { console.log('OK: unknown tool rejected ->', e.message); }

  // Test stable IDs
  const a = await callTool('note_create', {title: 'One', body: 'first'});
  const b = await callTool('note_create', {title: 'Two', body: 'second'});
  const aId = a.content[0].text.match(/n\d+/)[0];
  const bId = b.content[0].text.match(/n\d+/)[0];
  console.log('Stable IDs (sequential):', aId, bId);

  // Verify get returns same body
  const got = await callTool('note_get', {note_id: aId});
  console.log('Get matches title and body:', got.content[0].text.includes('One') && got.content[0].text.includes('first'));
});
